import './styles.css';

type ActivityCategory = 'Preparación' | 'Siembra' | 'Riego' | 'Fertilización' | 'Aplicación de insumo' | 'Monitoreo' | 'Gasto' | 'Incidente' | 'Cosecha';
interface Producer { name: string; phone: string; }
interface Farm { id: string; name: string; location: string; }
interface Plot { id: string; farmId: string; name: string; hectares: number; crop: string; cycle: string; stage: string; closed?: boolean; }
interface Activity { id: string; plotId: string; category: ActivityCategory; date: string; product?: string; objective?: string; dose?: number; unit?: string; hectares?: number; equipment?: string; responsible?: string; cost: number; notes?: string; draft?: boolean; createdAt: string; }
interface Harvest { plotId: string; date: string; hectares: number; production: number; unit: string; harvestCost: number; price: number; buyer?: string; }
interface Reminder { id: string; plotId: string; activity: string; date: string; time: string; repeat: string; responsible: string; notes?: string; done: boolean; }
interface Preferences { anonymousData: boolean; sponsoredOffers: boolean; location: boolean; }
interface AppData { producer?: Producer; farms: Farm[]; plots: Plot[]; activities: Activity[]; reminders: Reminder[]; harvests: Harvest[]; preferences: Preferences; setupDone: boolean; syncedAt: string; }

const KEY = 'libreta-digital-demo-v1';
const app = document.querySelector<HTMLDivElement>('#app')!;
const money = new Intl.NumberFormat('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 0 });
const dates = new Intl.DateTimeFormat('es-MX', { day: 'numeric', month: 'long', year: 'numeric' });
const glyphs: Record<string, string> = {
  home:'<path d="m3 10 9-7 9 7v9a2 2 0 0 1-2 2h-4v-6H9v6H5a2 2 0 0 1-2-2z"/>',
  map:'<path d="m9 18-6 3V6l6-3 6 3 6-3v15l-6 3z"/><path d="M9 3v15M15 6v15"/>',
  calendar:'<rect x="3" y="4" width="18" height="17" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
  chart:'<path d="M3 3v18h18"/><path d="M7 16v-5M12 16V7M17 16v-9"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', user:'<circle cx="12" cy="8" r="3"/><path d="M5 21a7 7 0 0 1 14 0"/>',
  cloud:'<path d="M17.5 19H9a6 6 0 1 1 1.5-11.8A5 5 0 0 1 20 10.5 4.5 4.5 0 0 1 17.5 19z"/><path d="M12 10v6M9.5 13.5 12 16l2.5-2.5"/>',
  layers:'<path d="m12 3 9 5-9 5-9-5z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/>', sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/>',
  droplet:'<path d="M12 2.5S5 10 5 15a7 7 0 0 0 14 0c0-5-7-12.5-7-12.5Z"/><path d="M9.5 16a3 3 0 0 0 3 3"/>', flask:'<path d="M9 3h6M10 3v6l-5 8a3 3 0 0 0 2.6 4h8.8A3 3 0 0 0 19 17l-5-8V3"/><path d="M7.5 15h9"/>',
  wheat:'<path d="M12 21V9M12 13c-3-1-4-3-4-5 3 0 4 2 4 5M12 17c-3-1-4-3-4-5 3 0 4 2 4 5M12 13c3-1 4-3 4-5-3 0-4 2-4 5M12 17c3-1 4-3 4-5-3 0-4 2-4 5"/>',
  tractor:'<path d="M3 18h2l2-7h6l2 4h3a3 3 0 0 1 3 3v1H3z"/><circle cx="7" cy="19" r="2"/><circle cx="18" cy="19" r="2"/><path d="M9 11V7h4v4"/>',
  sprout:'<path d="M12 21v-8M12 13C8 13 5 11 5 7c4 0 7 2 7 6M12 13c0-4 3-6 7-6 0 4-3 6-7 6"/>',
  target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/>', search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
  chevron:'<path d="m9 18 6-6-6-6"/>', back:'<path d="m15 18-6-6 6-6"/>', check:'<path d="m5 12 4 4L19 6"/>',
  alert:'<path d="m12 3 10 18H2z"/><path d="M12 9v4M12 17h.01"/>', file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>', coin:'<circle cx="12" cy="12" r="8"/><path d="M12 8v8M15 10.5c-.5-.7-1.5-1-3-1-1.5 0-2.5.7-2.5 1.7 0 2.8 5.5 1 5.5 3.5 0 1-1.1 1.8-3 1.8-1.5 0-2.7-.5-3.3-1.3"/>'
};
function ico(name: string, extra = '') { return `<svg class="ui-icon ${extra}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${glyphs[name] || glyphs.target}</svg>`; }
const icon: Record<string, string> = { 'Preparación': ico('tractor'), 'Siembra': ico('sprout'), 'Riego': ico('droplet'), 'Fertilización': ico('flask'), 'Aplicación de insumo': ico('target'), 'Monitoreo': ico('search'), 'Gasto': ico('coin'), 'Incidente': ico('alert'), 'Cosecha': ico('wheat') };
const categories: ActivityCategory[] = ['Preparación', 'Siembra', 'Riego', 'Fertilización', 'Aplicación de insumo', 'Monitoreo', 'Gasto', 'Incidente', 'Cosecha'];

function demoData(): AppData {
  const farm = { id: 'farm-roble', name: 'Rancho El Roble', location: 'Sinaloa, México' };
  const plot = { id: 'plot-norte', farmId: farm.id, name: 'Lote Norte', hectares: 24, crop: 'Maíz', cycle: 'Primavera-Verano 2026', stage: 'Desarrollo vegetativo' };
  return { producer: { name: 'Juan López', phone: '55 1234 5678' }, farms: [farm], plots: [plot],
    activities: [
      { id: 'act-demo-1', plotId: plot.id, category: 'Preparación', date: '2026-04-08', cost: 4200, responsible: 'Juan López', notes: 'Preparación inicial del terreno.', createdAt: '2026-04-08T08:00:00' },
      { id: 'act-demo-2', plotId: plot.id, category: 'Fertilización', date: '2026-04-15', cost: 5850, product: 'Fertilizante de ejemplo', dose: 12, unit: 'kg/ha', hectares: 24, responsible: 'Juan López', createdAt: '2026-04-15T08:00:00' },
      { id: 'act-demo-3', plotId: plot.id, category: 'Riego', date: '2026-04-19', cost: 8400, hectares: 24, responsible: 'Don Efraín', notes: 'Riego de apoyo.', createdAt: '2026-04-19T08:00:00' }
    ],
    reminders: [
      { id:'rem-1', plotId:plot.id, activity:'Riego', date:'2026-04-21', time:'06:00', repeat:'No se repite', responsible:'Juan López', notes:'Revisar humedad antes de iniciar.', done:false },
      { id:'rem-2', plotId:plot.id, activity:'Fertilización', date:'2026-04-23', time:'07:00', repeat:'No se repite', responsible:'Juan López', done:false },
      { id:'rem-3', plotId:plot.id, activity:'Monitoreo', date:'2026-04-24', time:'08:00', repeat:'Semanal', responsible:'Juan López', done:true }
    ], harvests: [], preferences: { anonymousData: true, sponsoredOffers: false, location: false }, setupDone: true, syncedAt: 'Hoy, 7:12 a.m.' };
}
function load(): AppData { try { const saved = localStorage.getItem(KEY); return saved ? JSON.parse(saved) as AppData : demoData(); } catch { return demoData(); } }
let state = load();
function save() { localStorage.setItem(KEY, JSON.stringify(state)); }
function id(prefix: string) { return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`; }
function go(route: string) { location.hash = `#/${route}`; }
function route(): string[] { const r = location.hash.replace(/^#\/?/, ''); return r ? r.split('/') : ['inicio']; }
function esc(value = '') { return String(value).replace(/[&<>'"]/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[char]!)); }
function fmtDate(value: string) { const d = new Date(`${value}T12:00:00`); return Number.isNaN(d.getTime()) ? value : dates.format(d); }
function plotById(plotId?: string) { return state.plots.find(p => p.id === plotId); }
function farmById(farmId?: string) { return state.farms.find(f => f.id === farmId); }
function plotCost(plotId: string) { return state.activities.filter(a => a.plotId === plotId && !a.draft).reduce((sum, a) => sum + a.cost, 0); }
function pendingCount() { return state.activities.filter(a => !a.draft).length ? 3 : 0; }
function page(content: string, nav = true, extra = '') { return `<main class="shell ${extra}">${content}${nav ? bottomNav() : ''}</main>`; }
function top(title: string, subtitle = '', back = '') { return `<header class="header"><div class="row gap-12">${back ? `<button class="back" data-route="${back}" aria-label="Volver">${ico('back')}</button>` : ''}<div><h1>${title}</h1>${subtitle ? `<p class="on-dark small" style="margin-top:4px">${subtitle}</p>` : ''}</div></div></header>`; }
function bottomNav() { const active = route()[0]; const is = (r: string) => active === r ? 'active' : ''; return `<nav class="nav no-print" aria-label="Navegación principal">
  <button class="${is('inicio')}" data-route="inicio">${ico('home')}<span>Inicio</span></button>
  <button class="${is('parcelas')}" data-route="parcelas">${ico('map')}<span>Parcelas</span></button>
  <button class="fab-wrap" data-route="registrar"><span class="fab">${ico('plus')}</span><span class="fab-label">Registrar</span></button>
  <button class="${is('agenda')}" data-route="agenda">${ico('calendar')}<span>Agenda</span></button>
  <button class="${is('reportes')}" data-route="reportes">${ico('chart')}<span>Reportes</span></button>
</nav>`; }
function demoBadge() { return `<span class="demo-label">● Prototipo demostrativo · Datos de ejemplo</span>`; }
function toast(message: string) { const el = document.createElement('div'); el.className = 'toast'; el.textContent = message; document.body.append(el); setTimeout(() => el.remove(), 2600); }
function stat(label: string, value: string) { return `<div class="stat"><span>${label}</span><b>${value}</b></div>`; }
function activityTitle(a: Activity) { return a.category === 'Aplicación de insumo' && a.product ? a.product : a.category; }

function welcome() { return page(`<header class="header center"><div class="brand-icon">▣</div><h1 style="font-size:25px">Libreta Digital</h1><p class="on-dark" style="margin-top:6px">El cuaderno de tu campo, siempre contigo</p></header><section class="content" style="display:flex;flex-direction:column"><h2 style="font-size:18px">Ingresa con tu número</h2><p class="muted" style="font-size:14px;margin:6px 0 24px">Te enviaremos un código de verificación por SMS.</p><form id="phone-form"><div class="field"><label>Número de celular</label><div class="row gap-8"><span class="strong">+52</span><input required class="input" name="phone" inputmode="numeric" placeholder="55 1234 5678" value="${esc(state.producer?.phone || '')}" /></div></div><button class="btn primary" type="submit">Enviar código <span>→</span></button></form><button class="btn secondary" data-route="inicio" style="margin-top:12px">Explorar demo</button><p class="small muted" style="text-align:center;margin:18px 8px">El envío de SMS es una simulación para este prototipo.</p><p class="login-note">⌁ Funciona incluso sin conexión a internet</p></section>`, false); }
function verify() { return page(`<header class="header center"><div class="brand-icon">▣</div><h1 style="font-size:24px">Verifica tu número</h1><p class="on-dark" style="margin-top:5px">Código de acceso simulado</p></header><section class="content"><p class="muted" style="margin-bottom:24px">Escribe el código enviado a <b>+52 ${esc(state.producer?.phone || '55 1234 5678')}</b>.</p><form id="verify-form"><div class="field"><label>Código de 6 dígitos</label><input class="input" required name="code" inputmode="numeric" maxlength="6" placeholder="123456" /></div><p class="small muted" style="margin:-5px 0 18px">Para este prototipo, utiliza el código <b>123456</b>.</p><button class="btn primary">Verificar código</button></form><button class="btn ghost" data-route="bienvenida" style="margin-top:14px">Cambiar número</button></section>`, false); }
function setup(step: number) {
  const info = step === 1 ? { title:'Cuéntanos sobre ti', sub:'Paso 1 de 3 · Datos básicos del productor' } : step === 2 ? { title:'Agrega tu primer predio', sub:'Paso 2 de 3 · Donde trabajas tu campo' } : { title:'Registra tu primera parcela', sub:'Paso 3 de 3 · Así llevarás el control desde el día uno' };
  let body = '';
  if (step === 1) body = `<div class="field"><label>Nombre del productor</label><input class="input" name="name" required value="${esc(state.producer?.name || '')}" placeholder="Ej. Juan López" /></div><div class="field"><label>Teléfono</label><input class="input" name="phone" value="${esc(state.producer?.phone || '')}" placeholder="55 1234 5678" /></div><p class="small muted">Esta información se guarda solo en este dispositivo como parte de la demostración.</p>`;
  if (step === 2) body = `<div class="field"><label>Nombre del predio</label><input class="input" name="farmName" required value="${esc(state.farms[0]?.name || '')}" placeholder="Ej. Rancho El Roble" /></div><div class="field"><label>Ubicación <span class="muted">(opcional)</span></label><input class="input" name="location" value="${esc(state.farms[0]?.location || '')}" placeholder="Municipio, estado" /></div><div class="card"><p class="small strong">⌂ No necesitas usar mapas</p><p class="small muted" style="margin-top:4px">La ubicación es solo una referencia escrita para este prototipo.</p></div>`;
  if (step === 3) body = `<div class="field"><label>Nombre de la parcela</label><input class="input" name="plotName" required value="${esc(state.plots[0]?.name || '')}" placeholder="Ej. Lote Norte" /></div><div class="field"><label>Hectáreas</label><div class="input-group"><input class="input" name="hectares" type="number" min="0.1" step="0.1" required value="${state.plots[0]?.hectares || ''}" /><span>ha</span></div></div><div class="field"><label>Cultivo principal</label><div class="choice-grid" data-choice="crop"><button type="button" class="choice active" data-value="Maíz">${ico('wheat')}<br>Maíz</button><button type="button" class="choice" data-value="Sorgo">${ico('sprout')}<br>Sorgo</button><button type="button" class="choice" data-value="Frijol">${ico('sprout')}<br>Frijol</button></div><input type="hidden" name="crop" value="Maíz"></div><div class="field"><label>Ciclo agrícola</label><input class="input" name="cycle" value="Primavera-Verano 2026" required /></div>`;
  return page(`${top(info.title, info.sub, step > 1 ? `configuracion/${step - 1}` : 'bienvenida')}<section class="content"><form id="setup-form" data-step="${step}">${body}<div class="setup-progress"><i class="active"></i><i class="${step>1?'active':''}"></i><i class="${step>2?'active':''}"></i></div><button class="btn primary" style="margin-top:26px">${step === 3 ? 'Finalizar configuración' : 'Continuar'} →</button></form></section>`, false); }
function home() { const plot = state.plots[0]; const tasks = state.reminders.filter(r => !r.done).slice(0, 2); return page(`<header class="header hero"><div class="row between"><button class="operation-selector" data-route="parcelas">${ico('layers')}<span>${state.farms[0]?.name || 'Todos mis predios'}</span>${ico('chevron')}</button><div class="hero-actions"><button class="circle-btn" data-action="sync">${ico('cloud')}<i class="badge-count">${pendingCount()}</i></button><button class="circle-btn" data-route="perfil">${ico('user')}</button></div></div><div class="row between hero-weather"><div><div class="weather">28°C</div><p class="on-dark hero-subtitle">Soleado · ${esc(plot?.name || 'Sin parcela')}</p></div><div class="sun-icon">${ico('sun')}</div></div><div class="status"><i class="status-dot"></i> ${navigator.onLine ? 'Con conexión · sincronización simulada' : 'Sin conexión'} · ${pendingCount()} registros</div><div class="hero-demo">${demoBadge()}</div></header><section class="content overlap home-content"><div class="chip-row"><button class="pill dark">Todos mis predios</button>${state.farms.map(f => `<button class="pill light" data-route="parcelas">${esc(f.name)}</button>`).join('')}</div><div class="card home-card"><div class="row between"><h2>Tareas próximas</h2><button class="btn ghost" style="width:auto;min-height:auto;padding:0" data-route="agenda">Ver todo</button></div>${tasks.length ? tasks.map(r => `<button class="history-item" data-route="agenda"><span class="small-icon ${r.activity === 'Fertilización' ? 'brown' : ''}">${icon[r.activity] || ico('calendar')}</span><span><b>${esc(r.activity)} · ${esc(plotById(r.plotId)?.name || '')}</b><small class="muted" style="display:block;margin-top:3px">${fmtDate(r.date)} · ${r.time}</small></span></button>`).join('') : `<p class="muted small" style="margin-top:14px">No tienes tareas próximas.</p>`}</div>${plot ? `<button class="card clickable home-cycle-card" data-route="parcela/${plot.id}"><h2>Ciclo activo</h2><div class="row gap-16 cycle-row"><span class="icon-tile green">${ico('wheat')}</span><span style="flex:1"><b>${esc(plot.crop)} · ${esc(plot.cycle)}</b><small class="muted" style="display:block;margin-top:4px">Etapa: ${esc(plot.stage)}</small></span><span class="progress-circle">62%</span></div></button>` : `<div class="card"><p class="muted">Agrega tu primera parcela para empezar.</p></div>`}</section>`); }
function plots() { return page(`<header class="header plots-header"><div class="row between"><h1>Mis parcelas</h1><span class="sync-chip">${ico('cloud')} ${navigator.onLine ? 'Con conexión' : 'Sin conexión'}</span></div><div class="search-field dark-search">${ico('search')}<input id="plot-search" class="input" placeholder="Buscar predio o parcela" /></div></header><section class="content">${state.farms.length ? state.farms.map(f => { const items = state.plots.filter(p=>p.farmId===f.id); return `<div class="property-title">${ico('home')} <h2>${esc(f.name)}</h2><span class="tiny muted">· ${items.length} parcela${items.length===1?'':'s'} · ${items.reduce((s,p)=>s+p.hectares,0)} ha</span></div>${items.length ? items.map(p=>`<button class="list-item searchable" data-route="parcela/${p.id}" data-search="${esc(f.name+' '+p.name)}"><span class="icon-tile ${p.crop === 'Maíz' ? 'green':'brown'}">${p.crop==='Maíz'?ico('wheat'):ico('sprout')}</span><span><b>${esc(p.name)}</b><small class="muted" style="display:block;margin-top:4px">${esc(p.crop)} · ${p.hectares} ha · ${esc(p.cycle)}</small><small style="display:block;color:#2E5C3E;font-weight:700;margin-top:5px">● ${esc(p.closed ? 'Ciclo cerrado' : p.stage)}</small></span><span class="chevron">${ico('chevron')}</span></button>`).join('') : `<div class="card small muted">Este predio aún no tiene parcelas.</div>`}`; }).join('') : `<div class="card empty"><div class="brand-icon">${ico('map')}</div><h2>Aún no tienes predios</h2><p class="muted small" style="margin-top:8px">Agrega un predio y sus parcelas para comenzar.</p></div>`}<div class="field-grid" style="margin-top:18px"><button class="btn outline" data-route="nuevo-predio">${ico('home')} Agregar predio</button><button class="btn outline" style="color:#8A5A34;border-color:#8A5A3488" data-route="nueva-parcela">${ico('plus')} Agregar parcela</button></div></section>`); }
function newFarm() { return page(`${top('Nuevo predio', '', 'parcelas')}<section class="content with-footer"><form id="farm-form"><div class="field"><label>Nombre del predio</label><input class="input" name="name" required placeholder="Ej. Rancho La Palma" /></div><div class="field"><label>Ubicación <span class="muted">(opcional)</span></label><input class="input" name="location" placeholder="Municipio, estado" /></div><p class="small muted">La ubicación se conserva localmente y no activa mapas ni geolocalización.</p><div class="footer-actions"><button class="btn primary">Guardar predio</button></div></form></section>`, false); }
function newPlot() { const farmOptions = state.farms.map(f => `<option value="${f.id}">${esc(f.name)}</option>`).join(''); return page(`${top('Nueva parcela', '', 'parcelas')}<section class="content with-footer"><form id="plot-form"><div class="field"><label>Predio</label><select class="select" name="farmId" required>${farmOptions || '<option value="">Primero agrega un predio</option>'}</select></div><div class="field"><label>Nombre de la parcela</label><input class="input" name="name" required placeholder="Ej. Lote Oriente" /></div><div class="field-grid"><div class="field"><label>Hectáreas</label><input class="input" type="number" min="0.1" step="0.1" name="hectares" required /></div><div class="field"><label>Cultivo</label><select class="select" name="crop"><option>Maíz</option><option>Sorgo</option><option>Frijol</option></select></div></div><div class="field"><label>Ciclo agrícola</label><input class="input" name="cycle" value="Primavera-Verano 2026" required /></div><div class="footer-actions"><button class="btn primary">Guardar parcela</button></div></form></section>`, false); }
function plotDetail(plotId: string) { const plot = plotById(plotId); if (!plot) return notFound(); const farm = farmById(plot.farmId); const acts = state.activities.filter(a=>a.plotId===plotId&&!a.draft).sort((a,b)=>b.date.localeCompare(a.date)); const reminders=state.reminders.filter(r=>r.plotId===plotId&&!r.done); const cost=plotCost(plotId); return page(`${top(plot.name, `${farm?.name || ''} · ${plot.crop} · ${plot.cycle}`, 'parcelas')}<section class="content overlap with-footer"><div class="card"><div class="row gap-12"><span class="icon-tile green">${ico('wheat')}</span><span><b>${esc(plot.crop)} · ${esc(plot.cycle)}</b><small class="muted" style="display:block;margin-top:4px">${plot.hectares} hectáreas · ${esc(plot.stage)}</small></span></div><div class="stats" style="margin-top:15px">${stat('Inversión acumulada', money.format(cost))}${stat('Costo por hectárea', money.format(cost / plot.hectares))}</div></div>${reminders.length?`<div class="card"><h2>Tareas próximas</h2>${reminders.map(r=>`<div class="task"><span class="small-icon">${icon[r.activity]||ico('calendar')}</span><span><b>${esc(r.activity)}</b><small class="muted" style="display:block;margin-top:3px">${fmtDate(r.date)} · ${r.time}</small></span></div>`).join('')}</div>`:''}${state.preferences.sponsoredOffers?`<div class="card sponsored"><span class="sponsored-label">Promoción patrocinada</span><div class="row gap-12" style="margin-top:7px"><span class="small-icon brown">${ico('coin')}</span><span><b>Insumo de ejemplo</b><small class="muted" style="display:block;margin-top:2px">Contenido demostrativo. Sin compra ni enlace externo.</small></span></div></div>`:''}<div class="card"><div class="row between"><h2>Historial de actividades</h2><span class="pill brown">${acts.length}</span></div>${acts.length?acts.map(a=>`<button class="history-item" data-route="actividad/${a.id}"><span class="small-icon ${a.category==='Gasto'?'brown':''}">${icon[a.category]}</span><span><b>${esc(activityTitle(a))}</b><small class="muted" style="display:block;margin-top:3px">${fmtDate(a.date)} · ${money.format(a.cost)}</small></span><span class="chevron">${ico('chevron')}</span></button>`).join(''):`<p class="small muted" style="margin-top:13px">No hay actividades registradas.</p>`}</div><div class="footer-actions"><button class="btn primary" data-route="registrar/${plotId}">${ico('plus')} Registrar actividad en esta parcela</button>${!plot.closed ? `<button class="btn ghost" data-route="cosecha/${plotId}" style="margin-top:4px">Registrar cosecha y cerrar ciclo</button>` : `<button class="btn secondary" data-route="resumen/${plotId}" style="margin-top:4px">Ver resumen de ciclo</button>`}</div></section>`, false); }
function activityPicker(plotId = '') { const plot = plotById(plotId); const global = !plot; return page(`${top('Registrar actividad', plot ? `${plot.name} · ${plot.crop}` : 'Elige una parcela y una actividad', plot ? `parcela/${plot.id}` : 'inicio')}<section class="content with-footer">${global ? `<div class="field"><label>Parcela</label><select id="picker-plot" class="select"><option value="">Selecciona una parcela</option>${state.plots.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(farmById(p.farmId)?.name || '')}</option>`).join('')}</select></div>`:''}<h2 class="picker-label">Actividad</h2><input type="hidden" id="picker-category" value="" /><div class="categories" style="margin-top:12px">${categories.map(c=>`<button class="category" data-action="select-activity-category" data-category="${c}"><span class="cat-icon">${icon[c]}</span><span>${c}</span></button>`).join('')}</div><p class="small muted" style="text-align:center;margin:20px 8px">Las categorías son registros demostrativos y se guardan en este dispositivo.</p><div class="footer-actions"><button class="btn primary" data-action="continue-activity" data-plot="${plotId}">Siguiente ${ico('chevron')}</button></div></section>`, false); }
function inputForm(plotId: string, category: ActivityCategory, editingId = '') { const plot = plotById(plotId); if (!plot) return activityPicker(); const editing = state.activities.find(a => a.id === editingId); const special = category === 'Aplicación de insumo'; const value = (key: keyof Activity, fallback = '') => esc(String(editing?.[key] ?? fallback)); return page(`${top(editing ? `Editar: ${category}` : category, `${plot.name} · ${plot.hectares} ha`, editing ? `actividad/${editing.id}` : `registrar/${plotId}`)}<section class="content with-footer"><form id="activity-form" data-plot="${plotId}" data-category="${category}" data-edit="${editingId}"><div class="field"><label>Fecha</label><input class="input" name="date" type="date" value="${value('date','2026-04-21')}" required /></div>${special?`<div class="field"><label>Producto</label><input class="input" name="product" required value="${value('product','Insecticida de ejemplo')}" /></div><div class="field"><label>Objetivo o plaga</label><input class="input" name="objective" value="${value('objective')}" placeholder="Ej. Insecto de ejemplo" /></div><div class="field-grid"><div class="field"><label>Dosis</label><input class="input calc-input" name="dose" type="number" step="0.01" value="${value('dose','0.25')}" required /></div><div class="field"><label>Unidad</label><select class="select" name="unit"><option ${editing?.unit==='L/ha'?'selected':''}>L/ha</option><option ${editing?.unit==='kg/ha'?'selected':''}>kg/ha</option><option ${editing?.unit==='ml/ha'?'selected':''}>ml/ha</option></select></div></div><div class="field"><label>Hectáreas atendidas</label><input class="input calc-input" name="hectares" type="number" step="0.1" value="${value('hectares',String(plot.hectares))}" required /></div><div class="calc">◈ <span><small class="muted">Cantidad total calculada</small><b id="total-dose" style="display:block">6 L</b></span></div><div class="field"><label>Equipo</label><input class="input" name="equipment" value="${value('equipment')}" placeholder="Ej. Aspersora" /></div>`:`<div class="field"><label>Hectáreas atendidas</label><input class="input" name="hectares" type="number" step="0.1" value="${value('hectares',String(plot.hectares))}" /></div>`}<div class="field"><label>Responsable</label><input class="input" name="responsible" value="${value('responsible',state.producer?.name || '')}" /></div><div class="field"><label>Costo</label><div class="input-group"><input class="input" name="cost" type="number" min="0" step="1" value="${value('cost','0')}" required /><span>MXN</span></div></div><div class="field"><label>Fotografía <span class="muted">(simulada)</span></label><button type="button" class="btn outline" data-action="photo">▣ Tomar o adjuntar foto</button></div><div class="field"><label>Notas <span class="muted">(opcional)</span></label><textarea name="notes" rows="3" placeholder="Detalles adicionales del registro...">${value('notes')}</textarea></div><div class="footer-actions"><button class="btn primary" name="save" value="record">${editing?'Guardar cambios':'Guardar registro'}</button>${editing?'':`<button class="btn ghost" name="save" value="draft" style="margin-top:3px">Guardar borrador</button>`}</div></form></section>`, false); }
function confirmation() { return page(`<section class="content" style="text-align:center;display:flex;min-height:100vh;flex-direction:column"><div class="success">✓</div><h1 style="color:#1F3A2A">Registro guardado</h1><p class="muted" style="margin:10px auto 20px;max-width:280px">La actividad se agregó al historial y quedó guardada en este dispositivo.</p><div class="card" style="text-align:left"><div class="row between"><span class="small">Estado de sincronización</span><span class="pill brown">Simulado · pendiente</span></div><p class="small muted" style="margin-top:10px">No se envió información a ningún servicio externo.</p></div><div style="margin-top:auto"><button class="btn primary" data-route="registrar">Registrar otra actividad</button><button class="btn ghost" data-route="inicio" style="margin-top:8px">Volver al inicio</button></div></section>`, false); }
function activityDetail(activityId: string) { const activity = state.activities.find(a=>a.id===activityId); if (!activity) return notFound(); const plot = plotById(activity.plotId); const detailed = [['Fecha',fmtDate(activity.date)],['Parcela',plot?.name||''],['Producto',activity.product],['Objetivo o plaga',activity.objective],['Dosis',activity.dose ? `${activity.dose} ${activity.unit||''}` : undefined],['Hectáreas atendidas',activity.hectares ? `${activity.hectares} ha` : undefined],['Equipo',activity.equipment],['Responsable',activity.responsible],['Costo',money.format(activity.cost)]].filter((x): x is [string,string] => Boolean(x[1])); return page(`${top(activityTitle(activity), plot?.name || '', `parcela/${activity.plotId}`)}<section class="content with-footer"><div class="card"><div class="row between"><span class="small">Estado de sincronización</span><span class="pill brown">☁ Pendiente · simulado</span></div><p class="small muted" style="margin-top:10px">Este registro se mantiene en el almacenamiento local del prototipo.</p></div><div class="card"><h2>Información del registro</h2>${detailed.map(([l,v])=>`<div class="row between" style="padding:11px 0;border-bottom:1px solid #3A3A3A12"><span class="small muted">${l}</span><b class="small">${esc(v)}</b></div>`).join('')}</div>${activity.notes?`<div class="card"><h2>Notas</h2><p class="small muted" style="margin-top:8px">${esc(activity.notes)}</p></div>`:''}<div class="footer-actions"><button class="btn secondary" data-action="edit-activity" data-id="${activity.id}">Editar</button><button class="btn ghost" data-action="duplicate-activity" data-id="${activity.id}" style="margin-top:3px">Duplicar</button><button class="btn danger" data-action="delete-activity" data-id="${activity.id}" style="margin-top:4px">Eliminar</button></div></section>`, false); }
function agenda() { const byDate=(date:string)=>state.reminders.find(r=>r.date===date&&!r.done); const completed=state.reminders.find(r=>r.done); const item=(reminder:Reminder|undefined, fallback:{activity:string;plot:string;note:string;kind:string})=>{const title=reminder?`${reminder.activity} · ${plotById(reminder.plotId)?.name||'Lote Norte'}`:fallback.activity+' · '+fallback.plot;const note=reminder?`${reminder.time} · Maíz PV2026`:fallback.note;const mark=reminder?`data-action="toggle-reminder" data-id="${reminder.id}"`:'';return `<div class="agenda-task ${fallback.kind==='alert'?'agenda-alert':''}"><span class="small-icon ${fallback.kind==='brown'||fallback.kind==='alert'?'brown':''}">${icon[reminder?.activity||fallback.activity]||ico(fallback.kind==='monitor'?'search':'calendar')}</span><span style="flex:1"><b>${esc(title)}</b><small class="muted" style="display:block;margin-top:3px">${esc(note)}</small></span><button class="check" ${mark} aria-label="Marcar como completado"></button></div>`;};return page(`<header class="header agenda-header"><div class="row between"><h1>Agenda</h1><button class="circle-btn agenda-add" data-route="nuevo-recordatorio" aria-label="Nuevo recordatorio">${ico('plus')}</button></div><div class="date-strip"><button class="date-tile active"><small>MAR</small><b>21</b></button><button class="date-tile"><small>MIÉ</small><b>22</b></button><button class="date-tile"><small>JUE</small><b>23</b></button><button class="date-tile has-task"><small>VIE</small><b>24</b></button><button class="date-tile"><small>SÁB</small><b>25</b></button></div></header><section class="content agenda-content"><div class="agenda-section"><h2>Hoy · Martes 21</h2>${item(byDate('2026-04-21'),{activity:'Riego',plot:'Lote Norte',note:'6:00 a.m. · Maíz PV2026',kind:'green'})}</div><div class="agenda-section"><h2>Mañana · Miércoles 22</h2>${item(byDate('2026-04-22'),{activity:'Monitoreo de plagas',plot:'Lote Norte',note:'Todo el día',kind:'monitor'})}</div><div class="agenda-section"><h2>Jueves 23 de abril</h2>${item(byDate('2026-04-23'),{activity:'Fertilización',plot:'Lote Norte',note:'Recordatorio · Insumo de ejemplo',kind:'alert'})}</div><div class="agenda-section completed"><h2>Completadas recientemente</h2><div class="agenda-task completed-task"><span class="small-icon">${ico('check')}</span><span><b>${esc(completed?`${completed.activity} · ${plotById(completed.plotId)?.name||'Lote Norte'}`:'Aplicación de insumo · Lote Norte')}</b><small class="muted" style="display:block;margin-top:3px">Lunes 20 de abril</small></span></div></div></section>`); }
function reminderForm() { return page(`${top('Nuevo recordatorio', '', 'agenda')}<section class="content with-footer"><form id="reminder-form"><div class="field"><label>Parcela</label><select class="select" name="plotId" required>${state.plots.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Actividad</label><select class="select" name="activity">${['Riego','Fertilización','Monitoreo','Aplicación de insumo','Cosecha'].map(a=>`<option>${a}</option>`).join('')}</select></div><div class="field-grid"><div class="field"><label>Fecha</label><input class="input" type="date" name="date" value="2026-04-23" required /></div><div class="field"><label>Hora</label><input class="input" type="time" name="time" value="06:00" required /></div></div><div class="field"><label>Repetición</label><select class="select" name="repeat"><option>No se repite</option><option>Diario</option><option>Semanal</option><option>Mensual</option></select></div><div class="field"><label>Responsable</label><input class="input" name="responsible" value="${esc(state.producer?.name || '')}" /></div><div class="field"><label>Notas <span class="muted">(opcional)</span></label><textarea name="notes" rows="3" placeholder="Detalles adicionales del recordatorio..."></textarea></div><div class="footer-actions"><button class="btn primary">Guardar recordatorio</button></div></form></section>`, false); }
function harvestForm(plotId: string) { const plot=plotById(plotId); if(!plot) return notFound(); return page(`${top('Registro de cosecha', `${plot.name} · ${plot.hectares} ha`, `parcela/${plotId}`)}<section class="content with-footer"><form id="harvest-form" data-plot="${plotId}"><div class="field"><label>Fecha</label><input class="input" name="date" type="date" value="2026-05-10" required /></div><div class="field"><label>Hectáreas cosechadas</label><div class="input-group"><input id="harvest-ha" class="input harvest-calc" name="hectares" type="number" min="0.1" step="0.1" value="${plot.hectares}" required/><span>ha</span></div></div><div class="field-grid"><div class="field"><label>Producción total</label><input id="harvest-production" class="input harvest-calc" name="production" type="number" min="0" step="0.1" value="139" required/></div><div class="field"><label>Unidad</label><select class="select" name="unit"><option>Toneladas</option><option>Kilogramos</option></select></div></div><div class="calc">◈ <span><small class="muted">Rendimiento por hectárea</small><b id="harvest-yield" style="display:block">5.79 ton/ha</b></span></div><div class="field"><label>Gastos de cosecha</label><div class="input-group"><input id="harvest-cost" class="input harvest-calc" name="harvestCost" type="number" min="0" value="4200" required/><span>MXN</span></div></div><div class="field"><label>Precio de venta</label><div class="input-group"><input id="harvest-price" class="input harvest-calc" name="price" type="number" min="0" value="5800" required/><span>MXN/ton</span></div></div><div class="calc">$ <span><small class="muted">Ingreso total calculado</small><b id="harvest-income" style="display:block">${money.format(139*5800)}</b></span></div><div class="field"><label>Comprador <span class="muted">(opcional)</span></label><input class="input" name="buyer" placeholder="Ej. Bodega de ejemplo" /></div><div class="footer-actions"><button class="btn primary">Guardar cosecha y ver resumen</button><button type="button" class="btn ghost" data-action="harvest-draft" style="margin-top:3px">Guardar borrador</button></div></form></section>`, false); }
function cycleSummary(plotId: string) { const plot=plotById(plotId); const harvest=state.harvests.find(h=>h.plotId===plotId); if(!plot||!harvest) return plot ? harvestForm(plotId) : notFound(); const inv=plotCost(plotId)+harvest.harvestCost; const income=harvest.production*harvest.price; const yieldPer=harvest.production/harvest.hectares; const profit=income-inv; return page(`${top('Resumen del ciclo', `${plot.name} · ${plot.crop} · ${plot.cycle}`, `parcela/${plotId}`)}<section class="content overlap with-footer"><div class="card" style="text-align:center"><small class="muted">Utilidad estimada del ciclo</small><div class="report-num" style="color:#2E5C3E;margin-top:4px">${money.format(profit)}</div><small class="muted">Ingresos menos inversión total</small></div><div class="stats">${stat('Inversión total',money.format(inv))}${stat('Producción total',`${harvest.production} ${harvest.unit==='Toneladas'?'ton':harvest.unit}`)}${stat('Costo por hectárea',money.format(inv/harvest.hectares))}${stat('Ingresos por venta',money.format(income))}</div><div class="card"><h2>Detalle del ciclo</h2>${[['Hectáreas cosechadas',`${harvest.hectares} ha`],['Rendimiento por hectárea',`${yieldPer.toFixed(2)} ton/ha`],['Precio de venta',`${money.format(harvest.price)} / ton`],['Gastos de cosecha',money.format(harvest.harvestCost)]].map(([a,b])=>`<div class="row between" style="padding:11px 0;border-bottom:1px solid #3A3A3A12"><span class="small muted">${a}</span><b class="small">${b}</b></div>`).join('')}</div><div class="footer-actions">${!plot.closed?`<button class="btn primary" data-action="finish-cycle" data-plot="${plotId}">⚑ Finalizar ciclo</button>`:`<button class="btn secondary" data-route="reportes">Ver reportes</button>`}</div></section>`, false); }
function reports() { const relevant=state.activities.filter(a=>!a.draft); const total=relevant.reduce((s,a)=>s+a.cost,0)+state.harvests.reduce((s,h)=>s+h.harvestCost,0); const hectares=state.plots[0]?.hectares||24; const harvest=state.harvests[0]; const categoryData=[['Fertilizantes',6200,'#2E5C3E'],['Semilla',5400,'#1F3A2A'],['Insumos',3100,'#8A5A34'],['Mano de obra',2450,'#C9A36A'],['Combustible',1300,'#3A3A3A']] as const; const activityBars=[['Prep.',72],['Siembra',72],['Riego',164],['Fert.',110],['Monit.',136],['Insumo',110]] as const; const yieldText=harvest?`${(harvest.production/harvest.hectares).toFixed(2)} ton/ha`:'5.79 ton/ha'; return page(`<header class="header report-header"><div class="row between"><h1>Reportes</h1><button class="report-export" data-route="exportar">${ico('chart')} Exportar</button></div><button class="report-cycle">Maíz · Ciclo PV 2026 ${ico('chevron')}</button></header><section class="content reports-content"><div class="chip-row report-filters"><button class="filter-chip">${ico('home')} Rancho El Roble ${ico('chevron')}</button><button class="filter-chip">${ico('map')} Lote Norte ${ico('chevron')}</button><button class="filter-chip">${ico('calendar')} Ciclo PV 2026 ${ico('chevron')}</button></div><div class="report-summary-card"><div><small>Costo por hectárea</small><b>${money.format(total/hectares)}</b></div><div><small>Inversión total</small><b>${money.format(total)}</b></div></div><div class="card report-card"><h2>Costos por categoría</h2><div class="donut-layout"><div class="donut-chart"><span>${money.format(total)}</span><small>Total</small></div><div class="donut-legend">${categoryData.map(([label,value,color])=>`<span><i style="background:${color}"></i>${label}<b>${Math.round(value/18450*100)}%</b></span>`).join('')}</div></div></div><div class="card report-card"><h2>Actividades registradas</h2><div class="activity-chart">${activityBars.map(([label,height])=>`<span><i style="height:${height}px"></i><small>${label}</small></span>`).join('')}</div></div>${harvest?`<div class="card yield-actual"><div class="row between"><h2>Rendimiento registrado</h2><span class="pill success">Cosecha finalizada</span></div><b>${yieldText}</b><small class="muted">${plotById(harvest.plotId)?.name||'Lote Norte'} · con base en la cosecha registrada</small></div>`:`<div class="card yield-pending"><h2>Rendimiento</h2><div>${ico('calendar')}<b>Todavía no hay datos suficientes para calcular el rendimiento</b><small>Se mostrará en cuanto registres la cosecha de esta parcela</small></div></div>`}<div class="card yield-actual demo-yield"><div class="row between"><h2>Rendimiento registrado</h2><span class="pill success">Cosecha finalizada</span></div><b>5.79 ton/ha</b><small class="muted">La Mesa · Ciclo Otoño-Invierno 2025, con base en la cosecha registrada</small></div></section>`); }
function exportPage() { const plot=state.plots[0]; return page(`<header class="header export-header"><button class="back" data-route="reportes" aria-label="Volver">${ico('back')}</button><h1>Exportar informe</h1></header><section class="content export-content with-footer"><div class="card export-summary"><span class="icon-tile pale">${ico('wheat')}</span><span><b>${esc(plot?.crop||'Maíz')} · ${esc(plot?.name||'Lote Norte')}</b><small class="muted" style="display:block;margin-top:4px">Ciclo ${esc(plot?.cycle||'Primavera-Verano 2026')}</small></span></div><section class="export-section"><h2>Incluir en el informe</h2><label class="report-option"><span>Historial de actividades</span><input checked type="checkbox" /><i>${ico('check')}</i></label><label class="report-option"><span>Costos e insumos</span><input checked type="checkbox" /><i>${ico('check')}</i></label><label class="report-option"><span>Rendimiento estimado</span><input checked type="checkbox" /><i>${ico('check')}</i></label><label class="report-option"><span>Fotografías adjuntas</span><input type="checkbox" /><i>${ico('check')}</i></label></section><section class="export-section"><h2>Formato del archivo</h2><div class="export-formats" data-choice="export"><button type="button" class="choice active" data-value="print">${ico('file')}<b>PDF</b></button><button type="button" class="choice" data-value="csv">${ico('file')}<b>Excel</b></button></div><input type="hidden" value="print" id="export-format" /></section><div class="export-note">${ico('alert')}<span>El archivo se guardará en tu dispositivo aunque no tengas señal</span></div><div class="footer-actions"><button class="btn primary" data-action="export">${ico('file')} Exportar informe</button></div></section>`, false); }
function privacy() { const p=state.preferences; return page(`${top('Privacidad y datos', 'Preferencias demostrativas guardadas localmente', 'perfil')}<section class="content"><div class="card"><div class="switch-row"><span><b class="small">Compartir datos anónimos</b><small class="muted" style="display:block;margin-top:3px">Para mejorar la aplicación.</small></span><input class="switch" type="checkbox" data-pref="anonymousData" ${p.anonymousData?'checked':''}/></div><div class="switch-row"><span><b class="small">Mostrar ofertas patrocinadas</b><small class="muted" style="display:block;margin-top:3px">Contenido identificado como patrocinado.</small></span><input class="switch" type="checkbox" data-pref="sponsoredOffers" ${p.sponsoredOffers?'checked':''}/></div><div class="switch-row"><span><b class="small">Usar ubicación para clima local</b><small class="muted" style="display:block;margin-top:3px">No solicita ubicación real en este prototipo.</small></span><input class="switch" type="checkbox" data-pref="location" ${p.location?'checked':''}/></div></div><div class="card"><p class="small muted">Estas opciones son simuladas: no transmiten datos, solicitan permisos ni se conectan a servicios externos.</p></div></section>`); }
function profile() { const producer=state.producer; const totalHa=state.plots.reduce((s,p)=>s+p.hectares,0); return page(`${top('Mi perfil', '', 'inicio')}<section class="content overlap"><div class="card" style="text-align:center"><div class="brand-icon" style="width:58px;height:58px;font-size:26px;background:#1F3A2A;color:white">♙</div><h2>${esc(producer?.name || 'Productor')}</h2><p class="small muted" style="margin-top:4px">+52 ${esc(producer?.phone || '')}</p></div><div class="card"><div class="row between"><h2>Predios que administro</h2><button class="btn ghost" data-route="parcelas" style="width:auto;min-height:auto;padding:0">Ver todos</button></div><div class="row gap-12" style="margin-top:13px"><span class="small-icon">⌂</span><span><b>${state.farms.length} predio${state.farms.length===1?'':'s'}</b><small class="muted" style="display:block;margin-top:3px">${state.plots.length} parcelas · ${totalHa} ha</small></span></div></div><div class="card"><h2>Sincronización</h2><div class="row between" style="margin-top:11px"><span class="small muted">Registros pendientes</span><b style="color:#8A5A34">${pendingCount()}</b></div><div class="row between" style="margin-top:11px"><span class="small muted">Última sincronización</span><b class="small">${state.syncedAt}</b></div><button class="btn secondary" data-action="sync" style="margin-top:13px">⟳ Sincronizar ahora</button></div><button class="list-item" data-route="privacidad"><span class="small-icon dark">♙</span><b>Privacidad y preferencias</b><span class="chevron">›</span></button><button class="list-item" data-action="help"><span class="small-icon">?</span><b>Ayuda y soporte</b><span class="chevron">›</span></button><button class="list-item" data-action="reset-demo"><span class="small-icon brown">↻</span><b>Restablecer datos de demostración</b><span class="chevron">›</span></button><button class="list-item" data-action="logout" style="color:#a73222"><span class="small-icon">↪</span><b>Cerrar sesión</b><span class="chevron">›</span></button></section>`, false); }
function notFound() { return page(`${top('No encontramos esta pantalla', '', 'inicio')}<section class="content"><div class="card empty"><div class="brand-icon">?</div><h2>Vuelve a empezar</h2><button class="btn primary" data-route="inicio" style="margin-top:18px">Ir al inicio</button></div></section>`); }

function render() {
  const [name, a, b] = route();
  const view: Record<string, () => string> = {
    bienvenida: home, verificar: home, inicio: home, parcelas: plots, 'nuevo-predio': newFarm, 'nueva-parcela': newPlot,
    agenda, 'nuevo-recordatorio': reminderForm, reportes: reports, exportar: exportPage, privacidad: privacy, perfil: profile, confirmacion: confirmation, configuracion: () => setup(Number(a) || 1),
    parcela: () => plotDetail(a), registrar: () => b ? inputForm(a, decodeURIComponent(b) as ActivityCategory) : activityPicker(a),
    actividad: () => activityDetail(a), editar: () => { const activity=state.activities.find(x=>x.id===a); return activity ? inputForm(activity.plotId, activity.category, activity.id) : notFound(); }, cosecha: () => harvestForm(a), resumen: () => cycleSummary(a)
  };
  app.innerHTML = (view[name] || notFound)();
  updateCalculations();
}
function fields(form: HTMLFormElement) { return Object.fromEntries(new FormData(form).entries()) as Record<string,string>; }
function selectChoice(button: HTMLElement) { const group = button.closest<HTMLElement>('[data-choice]'); if(!group) return; group.querySelectorAll('.choice').forEach(x=>x.classList.remove('active')); button.classList.add('active'); const input = group.parentElement?.querySelector<HTMLInputElement>('input[type="hidden"]'); if (input) input.value=button.dataset.value || ''; }
function updateCalculations() { const dose=app.querySelector<HTMLInputElement>('[name="dose"]'); const hectares=app.querySelector<HTMLInputElement>('[name="hectares"]'); const unit=app.querySelector<HTMLSelectElement>('[name="unit"]'); const total=app.querySelector('#total-dose'); if(dose&&hectares&&total) total.textContent=`${((Number(dose.value)||0)*(Number(hectares.value)||0)).toFixed(2).replace(/\.00$/,'')} ${unit?.value?.split('/')[0] || ''}`; const ha=app.querySelector<HTMLInputElement>('#harvest-ha'); const prod=app.querySelector<HTMLInputElement>('#harvest-production'); const price=app.querySelector<HTMLInputElement>('#harvest-price'); const y=app.querySelector('#harvest-yield'); const income=app.querySelector('#harvest-income'); if(ha&&prod){ const yieldNum=(Number(prod.value)||0)/(Number(ha.value)||1); if(y)y.textContent=`${yieldNum.toFixed(2)} ton/ha`; if(income)income.textContent=money.format((Number(prod.value)||0)*(Number(price?.value)||0)); } }
function download(name: string, body: string, type: string) { const blob = new Blob([body], {type}); const url=URL.createObjectURL(blob); const link=document.createElement('a'); link.href=url; link.download=name; link.click(); setTimeout(()=>URL.revokeObjectURL(url),500); }
function exportData() { const format=app.querySelector<HTMLInputElement>('#export-format')?.value || 'csv'; if(format==='print'){ window.print(); return; } if(format==='json'){ download('libreta-digital-demo.json', JSON.stringify(state,null,2), 'application/json'); toast('Copia JSON descargada.'); return; } const rows=[['fecha','parcela','categoría','producto','hectáreas','costo_mxn','notas'], ...state.activities.map(a=>[a.date,plotById(a.plotId)?.name||'',a.category,a.product||'',String(a.hectares||''),String(a.cost),a.notes||''])]; const csv=rows.map(row=>row.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n'); download('actividades-y-costos.csv',csv,'text/csv;charset=utf-8'); toast('Archivo CSV descargado.'); }

app.addEventListener('click', event => {
  const target=(event.target as HTMLElement).closest<HTMLElement>('[data-route], [data-action], .choice'); if(!target) return;
  if(target.classList.contains('choice')) { selectChoice(target); return; }
  const to=target.dataset.route; if(to){ go(to); return; }
  const action=target.dataset.action;
  if(action==='sync'){ state.syncedAt='Ahora mismo'; save(); toast('Sincronización simulada completada.'); render(); }
  if(action==='photo') toast('La fotografía es simulada en este prototipo.');
  if(action==='select-picker-plot'){ const select=app.querySelector<HTMLSelectElement>('#picker-plot'); if(select?.value) go(`registrar/${select.value}`); else toast('Selecciona una parcela para continuar.'); }
  if(action==='select-activity-category'){ const category=target.dataset.category; app.querySelectorAll('.category').forEach(button=>button.classList.remove('active')); target.classList.add('active'); const selected=app.querySelector<HTMLInputElement>('#picker-category'); if(selected) selected.value=category||''; }
  if(action==='continue-activity'){ const selectedPlot=target.dataset.plot || app.querySelector<HTMLSelectElement>('#picker-plot')?.value; const selectedCategory=app.querySelector<HTMLInputElement>('#picker-category')?.value; if(!selectedPlot || !selectedCategory){toast('Selecciona una parcela y una actividad.');return;} if(selectedCategory==='Cosecha') go(`cosecha/${selectedPlot}`); else go(`registrar/${selectedPlot}/${encodeURIComponent(selectedCategory)}`); }
  if(action==='choose-category'){ const plotId=target.dataset.plot; const category=target.dataset.category as ActivityCategory; if(!plotId){ toast('Selecciona primero una parcela.'); return; } if(category==='Cosecha') go(`cosecha/${plotId}`); else go(`registrar/${plotId}/${encodeURIComponent(category)}`); }
  if(action==='toggle-reminder'){ const r=state.reminders.find(x=>x.id===target.dataset.id); if(r){r.done=!r.done;save();render();} }
  if(action==='delete-reminder'){ if(confirm('¿Eliminar este recordatorio?')){state.reminders=state.reminders.filter(x=>x.id!==target.dataset.id);save();render();} }
  if(action==='delete-activity'){ const act=state.activities.find(x=>x.id===target.dataset.id); if(act&&confirm('¿Eliminar este registro? Esta acción solo afecta los datos locales.')){state.activities=state.activities.filter(x=>x.id!==act.id);save();go(`parcela/${act.plotId}`);} }
  if(action==='duplicate-activity'){ const act=state.activities.find(x=>x.id===target.dataset.id); if(act){const copy={...act,id:id('act'),date:'2026-04-21',createdAt:new Date().toISOString()};state.activities.push(copy);save();toast('Registro duplicado. Puedes editar sus datos.');go(`actividad/${copy.id}`);} }
  if(action==='edit-activity'){ const act=state.activities.find(x=>x.id===target.dataset.id); if(act) go(`editar/${act.id}`); }
  if(action==='finish-cycle'){ const plot=plotById(target.dataset.plot); if(plot&&confirm('¿Finalizar este ciclo agrícola?')){plot.closed=true;save();toast('Ciclo finalizado en modo demostración.');render();} }
  if(action==='harvest-draft') toast('Borrador de cosecha guardado de manera simulada.');
  if(action==='export') exportData();
  if(action==='help') toast('Ayuda demostrativa: tus datos se guardan en este navegador.');
  if(action==='reset-demo'){ if(confirm('¿Restablecer todos los datos de demostración?')){state=demoData();save();toast('Datos de demostración restablecidos.');go('inicio');} }
  if(action==='logout'){ if(confirm('¿Cerrar la sesión simulada?')){go('inicio');toast('Sesión simulada cerrada.');} }
});
app.addEventListener('change', event => { const el=event.target as HTMLInputElement; if(el.dataset.pref){ const key=el.dataset.pref as keyof Preferences; state.preferences[key]=el.checked;save();toast('Preferencia guardada localmente.'); } if(el.matches('.calc-input, .harvest-calc') || el.name==='unit') updateCalculations(); });
app.addEventListener('input', event => { const el=event.target as HTMLInputElement; if(el.matches('.calc-input, .harvest-calc')) updateCalculations(); if(el.id==='plot-search'){ const value=el.value.toLowerCase();app.querySelectorAll<HTMLElement>('.searchable').forEach(item=>item.style.display=item.dataset.search?.toLowerCase().includes(value)?'flex':'none'); } });
app.addEventListener('submit', event => { const form=event.target as HTMLFormElement; event.preventDefault(); const v=fields(form);
  if(form.id==='phone-form'){ state.producer={name:state.producer?.name||'',phone:v.phone};save();go('verificar'); }
  if(form.id==='verify-form'){ if(v.code==='123456'){ if(state.setupDone)go('inicio'); else go('configuracion/1'); } else toast('El código simulado es 123456.'); }
  if(form.id==='setup-form'){ const step=Number(form.dataset.step); if(step===1) state.producer={name:v.name,phone:v.phone}; if(step===2){const prev=state.farms[0];const farm={id:prev?.id||id('farm'),name:v.farmName,location:v.location};state.farms=prev?[farm,...state.farms.slice(1)]:[farm];} if(step===3){const farm=state.farms[0]||{id:id('farm'),name:'Mi predio',location:''};if(!state.farms.length)state.farms.push(farm);const prev=state.plots[0];const plot:Plot={id:prev?.id||id('plot'),farmId:farm.id,name:v.plotName,hectares:Number(v.hectares),crop:v.crop,cycle:v.cycle,stage:'Desarrollo vegetativo'};state.plots=prev?[plot,...state.plots.slice(1)]:[plot];state.setupDone=true;}save();go(step===3?'inicio':`configuracion/${step+1}`); }
  if(form.id==='farm-form'){ state.farms.push({id:id('farm'),name:v.name,location:v.location});save();go('parcelas'); }
  if(form.id==='plot-form'){ state.plots.push({id:id('plot'),farmId:v.farmId,name:v.name,hectares:Number(v.hectares),crop:v.crop,cycle:v.cycle,stage:'Preparación de suelo'});save();go('parcelas'); }
  if(form.id==='activity-form'){ const isDraft=(event.submitter as HTMLButtonElement)?.value==='draft'; const existing=state.activities.find(a=>a.id===form.dataset.edit); const a:Activity={id:existing?.id||id('act'),plotId:form.dataset.plot!,category:form.dataset.category as ActivityCategory,date:v.date,product:v.product,objective:v.objective,dose:Number(v.dose)||undefined,unit:v.unit,hectares:Number(v.hectares)||undefined,equipment:v.equipment,responsible:v.responsible,cost:Number(v.cost)||0,notes:v.notes,draft:isDraft,createdAt:existing?.createdAt||new Date().toISOString()};if(existing)state.activities=state.activities.map(x=>x.id===a.id?a:x);else state.activities.push(a);save(); if(existing){toast('Cambios guardados localmente.');go(`actividad/${a.id}`);}else if(isDraft){toast('Borrador guardado localmente.');go(`parcela/${a.plotId}`);}else go('confirmacion'); }
  if(form.id==='reminder-form'){ state.reminders.push({id:id('rem'),plotId:v.plotId,activity:v.activity,date:v.date,time:v.time,repeat:v.repeat,responsible:v.responsible,notes:v.notes,done:false});save();toast('Recordatorio creado.');go('agenda/pendientes'); }
  if(form.id==='harvest-form'){ const h:Harvest={plotId:form.dataset.plot!,date:v.date,hectares:Number(v.hectares),production:Number(v.production),unit:v.unit,harvestCost:Number(v.harvestCost),price:Number(v.price),buyer:v.buyer};state.harvests=state.harvests.filter(x=>x.plotId!==h.plotId);state.harvests.push(h);save();go(`resumen/${h.plotId}`); }
});
window.addEventListener('hashchange',render);
if(!location.hash) go('inicio'); else render();
